"""Command line entry point for the durable incident operations application."""

from __future__ import annotations

import argparse
import json
import sys
from http.server import ThreadingHTTPServer

from .escalation import EscalationWorker
from .exceptions import (
    IncidentNotFound,
    InvalidTransition,
    VersionConflict,
)
from .sqlite_store import SQLiteIncidentStore
from .web import create_server


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser(
        prog="python -m incident_ops.cli",
        description="Durable incident operations center",
    )
    result.add_argument("--db", required=True, help="path to the SQLite database")
    subcommands = result.add_subparsers(dest="command", required=True)

    serve = subcommands.add_parser("serve", help="run the HTTP server")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8080)

    ingest = subcommands.add_parser("ingest", help="ingest an alert from JSON")
    ingest.add_argument("alert", help="JSON object with the alert fields")

    list_cmd = subcommands.add_parser("list", help="list incidents")
    list_cmd.add_argument("--status")
    list_cmd.add_argument("--severity")
    list_cmd.add_argument("--owner")

    update = subcommands.add_parser("update", help="update an incident")
    update.add_argument("incident_id")
    update.add_argument("update_json", help="JSON object with update fields")

    escalate = subcommands.add_parser("escalate", help="run the escalation worker")
    escalate.add_argument("--worker-id", default="cli")
    escalate.add_argument("--max-incidents", type=int, default=None)

    subcommands.add_parser("export", help="export NDJSON to stdout")
    subcommands.add_parser("import", help="import NDJSON from stdin")

    return result


def _open_store(db_path: str) -> SQLiteIncidentStore:
    return SQLiteIncidentStore(db_path)


def _emit(value: object) -> None:
    sys.stdout.write(json.dumps(value, default=str) + "\n")
    sys.stdout.flush()


def _error(message: str) -> None:
    sys.stderr.write(f"error: {message}\n")
    sys.stderr.flush()


def _parse_json_arg(raw: str, label: str) -> dict:
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise _CliError(f"invalid JSON for {label}: {exc}")
    if not isinstance(value, dict):
        raise _CliError(f"{label} must be a JSON object")
    return value


class _CliError(Exception):
    pass


def main(argv: list[str] | None = None) -> int:
    args = parser().parse_args(argv)
    try:
        if args.command == "serve":
            return _cmd_serve(args)
        if args.command == "ingest":
            return _cmd_ingest(args)
        if args.command == "list":
            return _cmd_list(args)
        if args.command == "update":
            return _cmd_update(args)
        if args.command == "escalate":
            return _cmd_escalate(args)
        if args.command == "export":
            return _cmd_export(args)
        if args.command == "import":
            return _cmd_import(args)
    except _CliError as exc:
        _error(str(exc))
        return 2
    except (IncidentNotFound, InvalidTransition, VersionConflict) as exc:
        _error(str(exc))
        return 1
    except ValueError as exc:
        _error(str(exc))
        return 2
    return 0


def _cmd_serve(args: argparse.Namespace) -> int:
    store = _open_store(args.db)
    server: ThreadingHTTPServer = create_server(store, args.host, args.port)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.shutdown()
        server.server_close()
        store.close()
    return 0


def _cmd_ingest(args: argparse.Namespace) -> int:
    payload = _parse_json_arg(args.alert, "alert")
    fingerprint = payload.get("fingerprint")
    title = payload.get("title")
    severity = payload.get("severity")
    if not fingerprint:
        raise _CliError("fingerprint is required")
    if not title:
        raise _CliError("title is required")
    if severity is None:
        raise _CliError("severity is required")
    store = _open_store(args.db)
    try:
        incident, created = store.ingest_alert(
            fingerprint=fingerprint,
            title=str(title),
            severity=severity,
            source=payload.get("source", "unknown"),
            details=payload.get("details"),
            idempotency_key=payload.get("idempotency_key"),
        )
    finally:
        store.close()
    _emit(incident.to_dict())
    return 0


def _cmd_list(args: argparse.Namespace) -> int:
    store = _open_store(args.db)
    try:
        incidents = store.list(
            status=args.status, severity=args.severity, owner=args.owner
        )
    finally:
        store.close()
    for incident in incidents:
        _emit(incident.to_dict())
    return 0


def _cmd_update(args: argparse.Namespace) -> int:
    payload = _parse_json_arg(args.update_json, "update")
    if "expected_version" not in payload:
        raise _CliError("expected_version is required")
    try:
        expected_version = int(payload["expected_version"])
    except (TypeError, ValueError):
        raise _CliError("expected_version must be an integer")
    store = _open_store(args.db)
    try:
        incident = store.update(
            args.incident_id,
            expected_version=expected_version,
            owner=payload.get("owner"),
            status=payload.get("status"),
            idempotency_key=payload.get("idempotency_key"),
        )
    finally:
        store.close()
    _emit(incident.to_dict())
    return 0


def _cmd_escalate(args: argparse.Namespace) -> int:
    store = _open_store(args.db)
    try:
        worker = EscalationWorker(store, args.worker_id)
        results = worker.run_until_idle(max_incidents=args.max_incidents)
    finally:
        store.close()
    for incident in results:
        _emit(incident.to_dict())
    return 0


def _cmd_export(args: argparse.Namespace) -> int:
    store = _open_store(args.db)
    try:
        for record in store.export_records():
            sys.stdout.write(json.dumps(record) + "\n")
    finally:
        store.close()
    sys.stdout.flush()
    return 0


def _cmd_import(args: argparse.Namespace) -> int:
    records: list[tuple[str, dict]] = []
    for lineno, line in enumerate(sys.stdin, 1):
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError as exc:
            raise _CliError(f"invalid JSON on line {lineno}: {exc}")
        kind = record.get("type")
        data = record.get("data")
        if kind not in {"incident", "event"} or not isinstance(data, dict):
            raise _CliError(f"unknown export record on line {lineno}: {record!r}")
        records.append((kind, data))
    store = _open_store(args.db)
    try:
        store.import_records(records)
    finally:
        store.close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

