body { margin: 0; }

main {
  width: min(1100px, calc(100% - 24px));
  margin: 16px auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.app-header {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.eyebrow { color: var(--accent); font-weight: 700; text-transform: uppercase; letter-spacing: .08em; font-size: 12px; margin: 0 0 2px; }
h1, h2 { margin: 0; }
h1 { font-size: 22px; }

.summary {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}
.summary-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 4px;
  border-radius: 10px;
  background: #f5f8fd;
  border: 1px solid var(--border);
  min-width: 0;
}
.summary-value { font-size: 20px; font-weight: 800; }
.summary-label { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.summary-card.status-open { background: #fff4e6; }
.summary-card.status-acknowledged { background: #eaf0ff; }
.summary-card.status-resolved { background: #eafaf0; }
.summary-card.overdue { background: #fdecec; color: var(--danger); }

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
  min-width: 0;
}
.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}
.filters { display: flex; gap: 8px; align-items: end; flex-wrap: wrap; }
.filter-label { display: grid; gap: 4px; font-size: 12px; color: var(--muted); }

.alert-form {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}
.alert-form label { display: grid; gap: 4px; font-size: 12px; color: var(--muted); }

input, select, button {
  box-sizing: border-box;
  min-height: 40px;
  padding: 8px 10px;
  font: inherit;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  width: 100%;
}
button {
  border: 0;
  border-radius: 8px;
  color: var(--accent-ink);
  background: var(--accent);
  font-weight: 700;
  cursor: pointer;
  width: auto;
  padding: 0 16px;
}
button.secondary { background: #6b7a93; }
button.warn { background: var(--warn); }
button.danger { background: var(--danger); }
button:disabled { opacity: .5; cursor: not-allowed; }

.feedback {
  background: #f5f8fd;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 12px;
  margin: 0;
  min-height: 18px;
}
.feedback.error { background: #fdecec; border-color: #f3c4c0; color: var(--danger); }
.feedback.success { background: #eafaf0; border-color: #c4e8d2; color: var(--ok); }

.incident-list { display: flex; flex-direction: column; gap: 8px; }
.incident-row {
  display: grid;
  grid-template-columns: 56px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  cursor: pointer;
  background: #fff;
  min-width: 0;
}
.incident-row:hover { border-color: var(--accent); }
.incident-row.selected { border-color: var(--accent); box-shadow: 0 0 0 2px rgba(49,84,165,.18); }
.incident-row .meta { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.incident-row .row-title { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
