"use strict";

const app = document.getElementById("incident-app");
const feedbackEl = document.getElementById("feedback");
const summaryTotal = document.getElementById("summary-total");
const summaryOpen = document.getElementById("summary-open");
const summaryAck = document.getElementById("summary-acknowledged");
const summaryResolved = document.getElementById("summary-resolved");
const summaryOverdue = document.getElementById("summary-overdue");
const statusFilter = document.getElementById("status-filter");
const severityFilter = document.getElementById("severity-filter");
const incidentList = document.getElementById("incident-list");
const incidentDetail = document.getElementById("incident-detail");
const timelinePanel = document.getElementById("timeline");
const timelineList = document.getElementById("timeline-list");
const alertForm = document.getElementById("alert-form");
const escalateBtn = document.getElementById("escalate-action");

const state = {
  filters: { status: "", severity: "" },
  selectedId: null,
  incidents: [],
  selected: null,
  feedback: "",
};

function setFeedback(message, kind) {
  state.feedback = message || "";
  feedbackEl.textContent = state.feedback;
  feedbackEl.classList.remove("error", "success");
  if (kind) feedbackEl.classList.add(kind);
}

function fmtTime(ts) {
  if (ts == null) return "—";
  const d = new Date(ts * 1000);
  if (Number.isNaN(d.getTime())) return String(ts);
  return d.toLocaleString();
}

function sevClass(sev) { return "sev-" + (sev || "P4"); }

async function fetchJson(url, opts) {
  opts = opts || {};
  const res = await fetch(url, opts);
  let data = null;
  const text = await res.text();
  if (text) {
    try { data = JSON.parse(text); } catch (e) { data = { error: text }; }
  }
  return { status: res.status, data: data || {} };
}

async function loadSummary() {
  try {
    const { data } = await fetchJson("/api/summary");
    const byStatus = data.by_status || {};
    summaryTotal.textContent = String(data.total ?? 0);
    summaryOpen.textContent = String(byStatus.open ?? 0);
    summaryAck.textContent = String(byStatus.acknowledged ?? 0);
    summaryResolved.textContent = String(byStatus.resolved ?? 0);
    summaryOverdue.textContent = String(data.open_overdue ?? 0);
  } catch (e) {
    setFeedback("Could not load summary", "error");
  }
}

async function refresh() {
  const params = new URLSearchParams();
  if (state.filters.status) params.set("status", state.filters.status);
  if (state.filters.severity) params.set("severity", state.filters.severity);
  const qs = params.toString();
  try {
    const { status, data } = await fetchJson("/api/incidents" + (qs ? "?" + qs : ""));
    if (status >= 400) {
      setFeedback(data.error || "Could not load incidents", "error");
      state.incidents = [];
    } else {
      state.incidents = Array.isArray(data) ? data : [];
      setFeedback(state.incidents.length ? `Loaded ${state.incidents.length} incident(s)` : "No incidents match these filters");
    }
    renderList();
    await loadSummary();
    if (state.selectedId) {
      await loadDetail(state.selectedId);
    }
  } catch (e) {
    setFeedback("Network error loading incidents", "error");
  }
}

function renderList() {
  incidentList.replaceChildren();
  if (!state.incidents.length) {
    const empty = document.createElement("p");
    empty.className = "empty";
    empty.textContent = "No incidents to show.";
    incidentList.appendChild(empty);
    return;
  }
  for (const inc of state.incidents) {
    const row = document.createElement("article");
    row.className = "incident-row";
    row.dataset.testid = "incident-row";
    row.setAttribute("data-testid", "incident-row");
    row.dataset.id = inc.id;
    if (inc.id === state.selectedId) row.classList.add("selected");
    const sev = document.createElement("span");
    sev.className = "sev-badge " + sevClass(inc.severity);
    sev.textContent = inc.severity;
    const meta = document.createElement("div");
    meta.className = "meta";
    const title = document.createElement("div");
    title.className = "row-title";
    title.textContent = inc.title;
    const sub = document.createElement("div");
    sub.className = "row-sub";
    sub.textContent = `${inc.alert_count} alert(s) · v${inc.version} · ${inc.owner || "unowned"}`;
    meta.appendChild(title);
    meta.appendChild(sub);
    const statusEl = document.createElement("span");
    statusEl.className = "row-status";
    const dot = document.createElement("span");
    dot.className = "status-dot dot-" + inc.status;
    statusEl.appendChild(dot);
    statusEl.appendChild(document.createTextNode(" " + inc.status));
    row.append(sev, meta, statusEl);
    row.addEventListener("click", () => selectIncident(inc.id));
    incidentList.appendChild(row);
  }
}

async function loadDetail(id) {
  try {
    const { status, data } = await fetchJson("/api/incidents/" + encodeURIComponent(id));
    if (status === 404) {
      state.selectedId = null;
      state.selected = null;
      incidentDetail.hidden = true;
      timelinePanel.hidden = true;
      setFeedback("Incident not found", "error");
      return;
    }
    if (status >= 400) {
      setFeedback(data.error || "Could not load incident", "error");
      return;
    }
    state.selected = data;
    state.selectedId = id;
    renderDetail();
    renderTimeline(data.events || []);
    renderList();
  } catch (e) {
    setFeedback("Network error loading detail", "error");
  }
}

function selectIncident(id) {
  state.selectedId = id;
  if (id == null) {
    state.selected = null;
    incidentDetail.hidden = true;
    timelinePanel.hidden = true;
  } else {
    loadDetail(id);
  }
  renderList();
}

function renderDetail() {
  const inc = state.selected;
  if (!inc) {
    incidentDetail.hidden = true;
    return;
  }
  incidentDetail.hidden = false;
  document.getElementById("detail-title").textContent = inc.title;
  document.getElementById("detail-version").textContent = "version " + inc.version;
  document.getElementById("detail-id").textContent = inc.id;
  const sevEl = document.getElementById("detail-severity");
  sevEl.textContent = inc.severity;
  sevEl.className = "sev-badge " + sevClass(inc.severity);
  document.getElementById("detail-status").textContent = inc.status;
  document.getElementById("detail-fingerprint").textContent = inc.fingerprint || "—";
  document.getElementById("detail-owner").textContent = inc.owner || "—";
  document.getElementById("detail-alert-count").textContent = String(inc.alert_count);
  document.getElementById("detail-escalation").textContent = String(inc.escalation_level);
  document.getElementById("detail-created").textContent = fmtTime(inc.created_at);
  document.getElementById("detail-updated").textContent = fmtTime(inc.updated_at);
  document.getElementById("detail-sla").textContent = fmtTime(inc.sla_deadline);
  const ownerInput = document.getElementById("owner-input");
  ownerInput.value = inc.owner || "";
  const ackBtn = document.getElementById("acknowledge-action");
  const resBtn = document.getElementById("resolve-action");
  ackBtn.disabled = inc.status !== "open";
  resBtn.disabled = inc.status === "resolved";
  timelinePanel.hidden = false;
}

function renderTimeline(events) {
  timelineList.replaceChildren();
  if (!events.length) {
    const empty = document.createElement("li");
    empty.className = "empty";
    empty.textContent = "No audit events yet.";
    timelineList.appendChild(empty);
    return;
  }
  for (const ev of events) {
    const li = document.createElement("li");
    li.className = "timeline-item";
    const time = document.createElement("div");
    time.className = "timeline-time";
    time.textContent = fmtTime(ev.timestamp);
    const body = document.createElement("div");
    body.className = "timeline-body";
    const typeEl = document.createElement("div");
    typeEl.className = "timeline-type";
    typeEl.textContent = (ev.type || "").replace(/_/g, " ");
    const detEl = document.createElement("div");
    detEl.className = "timeline-details";
    detEl.textContent = JSON.stringify(ev.details || {});
    body.appendChild(typeEl);
    body.appendChild(detEl);
    li.append(time, body);
    timelineList.appendChild(li);
  }
}

async function patchIncident(payload) {
  const inc = state.selected;
  if (!inc) return;
  payload.expected_version = inc.version;
  const { status, data } = await fetchJson("/api/incidents/" + encodeURIComponent(inc.id), {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (status === 409) {
    setFeedback(data.error ? `Conflict: ${data.error}` : "Version conflict — refresh and retry", "error");
    await loadDetail(inc.id);
    return;
  }
  if (status >= 400) {
    setFeedback(data.error || "Update failed", "error");
    if (status !== 404) await loadDetail(inc.id);
    return;
  }
  setFeedback("Incident updated", "success");
  await loadDetail(inc.id);
  await refresh();
}

document.getElementById("acknowledge-action").addEventListener("click", () => {
  patchIncident({ status: "acknowledged" });
});

document.getElementById("resolve-action").addEventListener("click", () => {
  patchIncident({ status: "resolved" });
});

document.getElementById("owner-input").addEventListener("change", (e) => {
  patchIncident({ owner: e.target.value });
});

statusFilter.addEventListener("change", (e) => {
  state.filters.status = e.target.value;
  refresh();
});

severityFilter.addEventListener("change", (e) => {
  state.filters.severity = e.target.value;
  refresh();
});

alertForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  const data = new FormData(alertForm);
  const payload = Object.fromEntries(data.entries());
  if (!payload.severity) delete payload.severity;
  const { status, data: body } = await fetchJson("/api/alerts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (status >= 400) {
    setFeedback(body.error || "Could not ingest alert", "error");
    return;
  }
  setFeedback(status === 201 ? "Incident created" : "Alert merged into existing incident", "success");
  alertForm.reset();
  await refresh();
  await selectIncident(body.id);
});

escalateBtn.addEventListener("click", async () => {
  const { status, data } = await fetchJson("/api/escalations/run?worker_id=browser", {
    method: "POST",
  });
