// errors. Exits nonzero on failure.
const { JSDOM } = require("jsdom");
const http = require("http");

const BASE = process.env.BASE_URL || "http://127.0.0.1:8080";

function fetchText(path) {
  return new Promise((resolve, reject) => {
    http.get(BASE + path, (res) => {
      let data = "";
      res.on("data", (c) => (data += c));
      res.on("end", () => resolve({ status: res.statusCode, body: data, headers: res.headers }));
    }).on("error", reject);
  });
}

function fetchJson(method, path, body) {
  return new Promise((resolve, reject) => {
    const opts = { method, hostname: "127.0.0.1", port: 8080, path, headers: {} };
    if (body !== undefined) {
      opts.headers["Content-Type"] = "application/json";
      opts.headers["Content-Length"] = Buffer.byteLength(body);
    }
    const req = http.request(opts, (res) => {
      let data = "";
      res.on("data", (c) => (data += c));
      res.on("end", () => {
        let parsed = null;
        try { parsed = JSON.parse(data); } catch (e) { parsed = data; }
        resolve({ status: res.statusCode, data: parsed });
      });
    });
    req.on("error", reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

const failures = [];
function check(cond, msg) {
  if (!cond) failures.push(msg);
  console.log((cond ? "PASS" : "FAIL") + ": " + msg);
}

async function main() {
  const indexRes = await fetchText("/");
  check(indexRes.status === 200, "GET / returns 200");

  const consoleErrors = [];
  const virtualConsole = new (require("jsdom").VirtualConsole)();
  virtualConsole.on("jsdomError", (e) => consoleErrors.push(e.message));
  virtualConsole.on("error", (...a) => consoleErrors.push(a.join(" ")));

  const dom = new JSDOM(indexRes.body, {
    runScripts: "dangerously",
    resources: "usable",
    url: BASE + "/",
    virtualConsole,
    beforeParse(win) {
      // Polyfill fetch in the window using node http
      win.fetch = (url, opts) => {
        opts = opts || {};
        const method = opts.method || "GET";
        let path = url.replace(BASE, "");
        const body = opts.body;
        return fetchJson(method, path, body).then(({ status, data }) => ({
          status,
          ok: status < 400,
          text: () => Promise.resolve(typeof data === "string" ? data : JSON.stringify(data)),
          json: () => Promise.resolve(data),
        }));
      };
    },
  });

  const win = dom.window;
  // Wait for scripts/resources to load and initial refresh
  await new Promise((r) => (win.addEventListener ? win.addEventListener("load", r) : setTimeout(r, 500)));
  await new Promise((r) => setTimeout(r, 1500));

  check(typeof win.incidentOps === "object", "window.incidentOps exposed");
  check(win.document.querySelector('[data-testid="incident-app"]') !== null, "incident-app marker");
  for (const m of ["summary","incident-list","incident-detail","timeline","status-filter","severity-filter","owner-input","acknowledge-action","resolve-action","feedback"]) {
    check(win.document.querySelector(`[data-testid="${m}"]`) !== null, `marker: ${m}`);
  }

  // Ingest an alert via the API then refresh
  await fetchJson("POST", "/api/alerts", JSON.stringify({ fingerprint: "fp1", title: "Browser test", severity: "P1" }));
  await win.incidentOps.refresh();
  await new Promise((r) => setTimeout(r, 300));

  const state = win.incidentOps.getState();
  check(Array.isArray(state.incidents) && state.incidents.length > 0, "getState returns incidents");
  check(typeof state.filters === "object", "getState returns filters");
  check("feedback" in state, "getState returns feedback");
  check(typeof state.selectedIncidentId !== "undefined", "getState returns selected incident id");

  const rows = win.document.querySelectorAll('[data-testid="incident-row"]');
  check(rows.length > 0, "incident rows rendered");

  // Select an incident and verify detail shows
  const firstId = state.incidents[0].id;
  await win.incidentOps.selectIncident(firstId);
  await new Promise((r) => setTimeout(r, 400));
  const detail = win.document.querySelector('[data-testid="incident-detail"]');
  check(detail && !detail.hidden, "incident detail shown after select");
  const timeline = win.document.querySelector('[data-testid="timeline"]');
  check(timeline && !timeline.hidden, "timeline shown after select");
  const timelineItems = win.document.querySelectorAll("#timeline-list .timeline-item");
  check(timelineItems.length > 0, "audit timeline populated");

  // Acknowledge action
  const ackBtn = win.document.querySelector('[data-testid="acknowledge-action"]');
  check(ackBtn !== null, "acknowledge action present");
  ackBtn.dispatchEvent(new win.Event("click"));
  await new Promise((r) => setTimeout(r, 600));
  check(/updated|acknowledge/i.test(win.incidentOps.getState().feedback), "feedback after acknowledge");

  console.log("\nConsole errors: " + consoleErrors.length);
  consoleErrors.forEach((e) => console.log("  CONSOLE ERROR: " + e));
  check(consoleErrors.length === 0, "no console errors");

  dom.window.close();
  if (failures.length) {
    console.error("\n" + failures.length + " FAILURE(S)");
    process.exit(1);
  } else {
    console.log("\nALL BROWSER CHECKS PASSED");
    process.exit(0);
  }
}

main().catch((e) => { console.error(e); process.exit(1); });

