"use strict";

const app = document.getElementById("incident-app");
const feedbackEl = document.getElementById("feedback");
const summaryTotal = document.getElementById("summary-total");
const summaryOpen = document.getElementById("summary-open");
const summaryAck = document.getElementById("summary-acknowledged");
const summaryResolved = document.getElementById("summary-resolved");
const summaryOverdue = document.getElementById("summary-overdue");
const statusFilter = document.getElementById("status-filter");
const severityFilter = document.getElementById("severity-filter");
const incidentList = document.getElementById("incident-list");
const incidentDetail = document.getElementById("incident-detail");
const timelinePanel = document.getElementById("timeline");
const timelineList = document.getElementById("timeline-list");
const alertForm = document.getElementById("alert-form");
const escalateBtn = document.getElementById("escalate-action");

const state = {
  filters: { status: "", severity: "" },
  selectedId: null,
  incidents: [],
  selected: null,
  feedback: "",
};

function setFeedback(message, kind) {
  state.feedback = message || "";
  feedbackEl.textContent = state.feedback;
  feedbackEl.classList.remove("error", "success");
  if (kind) feedbackEl.classList.add(kind);
}

function fmtTime(ts) {
  if (ts == null) return "—";
  const d = new Date(ts * 1000);
  if (Number.isNaN(d.getTime())) return String(ts);
  return d.toLocaleString();
}

function sevClass(sev) { return "sev-" + (sev || "P4"); }

async function fetchJson(url, opts) {
  opts = opts || {};
  const res = await fetch(url, opts);
  let data = null;
  const text = await res.text();
  if (text) {
    try { data = JSON.parse(text); } catch (e) { data = { error: text }; }
  }
  return { status: res.status, data: data || {} };
}

async function loadSummary() {
  try {
    const { data } = await fetchJson("/api/summary");
    const byStatus = data.by_status || {};
    summaryTotal.textContent = String(data.total ?? 0);
    summaryOpen.textContent = String(byStatus.open ?? 0);
    summaryAck.textContent = String(byStatus.acknowledged ?? 0);
    summaryResolved.textContent = String(byStatus.resolved ?? 0);
    summaryOverdue.textContent = String(data.open_overdue ?? 0);
  } catch (e) {
    setFeedback("Could not load summary", "error");
  }
}

async function refresh() {
  const params = new URLSearchParams();
  if (state.filters.status) params.set("status", state.filters.status);
  if (state.filters.severity) params.set("severity", state.filters.severity);
  const qs = params.toString();
  try {
    const { status, data } = await fetchJson("/api/incidents" + (qs ? "?" + qs : ""));
    if (status >= 400) {
      setFeedback(data.error || "Could not load incidents", "error");
      state.incidents = [];
    } else {
      state.incidents = Array.isArray(data) ? data : [];
      setFeedback(state.incidents.length ? `Loaded ${state.incidents.length} incident(s)` : "No incidents match these filters");
    }
    renderList();
    await loadSummary();
    if (state.selectedId) {
      await loadDetail(state.selectedId);
    }
  } catch (e) {
    setFeedback("Network error loading incidents", "error");
  }
}

function renderList() {
  incidentList.replaceChildren();
  if (!state.incidents.length) {
    const empty = document.createElement("p");
    empty.className = "empty";
    empty.textContent = "No incidents to show.";
    incidentList.appendChild(empty);
    return;
  }
  for (const inc of state.incidents) {
    const row = document.createElement("article");
    row.className = "incident-row";
    row.dataset.testid = "incident-row";
    row.setAttribute("data-testid", "incident-row");
    row.dataset.id = inc.id;
    if (inc.id === state.selectedId) row.classList.add("selected");
    const sev = document.createElement("span");
    sev.className = "sev-badge " + sevClass(inc.severity);
    sev.textContent = inc.severity;
    const meta = document.createElement("div");
    meta.className = "meta";
    const title = document.createElement("div");
    title.className = "row-title";
    title.textContent = inc.title;
    const sub = document.createElement("div");
    sub.className = "row-sub";
    sub.textContent = `${inc.alert_count} alert(s) · v${inc.version} · ${inc.owner || "unowned"}`;
    meta.appendChild(title);
    meta.appendChild(sub);
    const statusEl = document.createElement("span");
    statusEl.className = "row-status";
    const dot = document.createElement("span");
    dot.className = "status-dot dot-" + inc.status;
    statusEl.appendChild(dot);
    statusEl.appendChild(document.createTextNode(" " + inc.status));
    row.append(sev, meta, statusEl);
    row.addEventListener("click", () => selectIncident(inc.id));
    incidentList.appendChild(row);
  }
}

async function loadDetail(id) {
  try {
    const { status, data } = await fetchJson("/api/incidents/" + encodeURIComponent(id));
    if (status === 404) {
      state.selectedId = null;
      state.selected = null;
      incidentDetail.hidden = true;
      timelinePanel.hidden = true;
      setFeedback("Incident not found", "error");
      return;
    }
    if (status >= 400) {
      setFeedback(data.error || "Could not load incident", "error");
      return;
    }
    state.selected = data;
    state.selectedId = id;
    renderDetail();
    renderTimeline(data.events || []);
    renderList();
  } catch (e) {
    setFeedback("Network error loading detail", "error");
  }
